mapper.update:
UPDATE BOARD
BOARD_TITLE = #{boardTitle}, INTRODUCE = #{introduce}, IMAGE_URL = #{imageUrl}, URL = #{url}, OPEN = #{open},
WHERE BOARD_NO = #{boardNo}

UPDATE TAG
TYPE_NAME = #{typeName}, DIFFICULT = #{difficult}, COOK_TIME = #{cookTime}, CALORY = #{calory},
WHERE TYPE_NO = #{typeNo}

update.foreach:
UPDATE INGREDIENT
INGREDIENT_NAME = #{ing.ingredientName}, QUANTITY = #{ing.quantity}, UNIT = #{ing.unit},
WHERE INGREDIENT_NO = #{ing.ingredientNo}

UPDATE COOK_STEP
COOK_CONTENT = #{step.cookContent}, COOK_IMAGE = #{step.cookImage},
WHERE BOARD_NO = #{step.boardNo} AND STEP = #{step.step}

mapper.select:
SELECT COUNT(*)
FROM REPORT
WHERE USER_NO = #{userNo}
  AND COMMENT_NO = #{commentNo}
